INSERT INTO repo_kcrs (kcr_id, name, domain, concept_category, concept_type, definition, scope, core_principles, semantic_description, keywords_synonyms, status) VALUES ('KCR_000001', 'Classes', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'An object-oriented programming construct that defines the attributes/state and operations/behaviour shared by objects of the class.', 'Class definitions, objects/instances, attributes, methods, encapsulation, abstraction, constructors, visibility and implementation of abstract data types.', 'Abstraction; encapsulation; state and behaviour; modularity; information hiding.', 'Classes provide a blueprint for objects by combining state representation with operations. They support abstraction and encapsulation and are commonly used to implement reusable data abstractions.', 'Object-oriented programming; data abstraction; ADTs', 'Active'), ('KCR_000002', 'Stacks', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'A linear abstract data type in which insertion and deletion occur at one designated end, following last-in-first-out (LIFO) order.', 'Push, pop, peek/top, underflow/overflow conditions, array- and linked implementations, and time/space complexity.', 'LIFO ordering; abstraction; access restriction; operation complexity.', 'A stack restricts access to the most recently inserted element. Its operations are typically O(1) with suitable implementations and it is used for recursion, expression evaluation and backtracking.', 'LIFO; push/pop; ADT; underflow/overflow', 'Active'), ('KCR_000003', 'Queues', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'A linear abstract data type in which insertion is performed at one end and deletion at the other, following first-in-first-out (FIFO) order.', 'Enqueue, dequeue, front/rear operations, circular queues, array/linked implementations, and underflow/overflow conditions.', 'FIFO ordering; abstraction; controlled access; operation complexity.', 'A queue models ordered service in which the earliest inserted item is normally removed first. Circular and linked implementations can provide efficient enqueue/dequeue operations.', 'FIFO; enqueue/dequeue; circular queue; ADT', 'Active'), ('KCR_000004', 'Linked Lists', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'A linked linear data structure consisting of nodes that contain data and one or more links to other nodes.', 'Singly, doubly and circular lists; insertion/deletion; traversal; node references; memory representation and complexity.', 'Dynamic linkage; pointer/reference integrity; structural flexibility; operation complexity.', 'Linked lists represent sequences through node links rather than contiguous storage. They support efficient insertion/deletion when the relevant position or node is known, but sequential access is required for traversal.', 'Nodes; pointers/references; dynamic data structures', 'Active'), ('KCR_000005', 'Binary Search Tree (BST)', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'A binary tree in which keys in the left subtree are ordered relative to the node key and keys in the right subtree are ordered in the opposite direction, according to the chosen ordering rule.', 'Search, insertion, deletion, traversal, ordering invariant, height and best/average/worst-case complexity.', 'Ordering invariant; recursive structure; search efficiency; height dependence.', 'A binary search tree maintains an ordering property that supports ordered search and update operations. Its performance depends on tree height, ranging from logarithmic for balanced shapes to linear for a degenerate tree.', 'Binary trees; ordering; recursion', 'Active'), ('KCR_000006', 'AVL Trees', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'A self-balancing binary search tree in which the height difference between the left and right subtrees of every node is bounded by one.', 'Balance factor, rotations, insertion/deletion rebalancing, search and height guarantees.', 'Height balance; ordering invariant; rotations; logarithmic height.', 'AVL trees maintain the BST ordering property while using rotations after updates to keep height logarithmic, giving O(log n) search, insertion and deletion in the standard model.', 'BST; balance factor; rotations', 'Active'), ('KCR_000007', 'Quick/Merge sort', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'Comparison-based sorting methods represented here by Quicksort and Mergesort, which organize elements into sorted order using divide-and-conquer strategies.', 'Partitioning and recursive subproblems in Quicksort; splitting and merging in Mergesort; stability, in-place behaviour and time/space complexity.', 'Divide and conquer; ordering; complexity; partitioning/merging.', 'Quicksort partitions around a pivot and has average O(n log n) time but O(n²) worst-case time for poor pivot choices. Mergesort uses merging of sorted sublists and has O(n log n) time, typically requiring additional storage for arrays.', 'Quicksort; Mergesort; divide and conquer', 'Active'), ('KCR_000008', 'Binary Search', 'Engineering & Technology', 'Data Structures & Algorithms', 'Method / Process', 'A search algorithm that repeatedly compares a target with the middle element of an ordered sequence and eliminates half of the remaining search interval.', 'Sorted data requirement, iterative/recursive implementation, interval reduction and complexity.', 'Ordering; divide and conquer; logarithmic search.', 'Binary search achieves O(log n) comparisons when applied to an ordered structure that supports efficient midpoint access, such as an array.', 'Sorted sequence; comparison; interval halving', 'Active'), ('KCR_000009', 'Collision resolution', 'Engineering & Technology', 'Data Structures & Algorithms', 'Technical Concept', 'Techniques used in hash tables to handle multiple keys that map to the same table location.', 'Separate chaining, open addressing, probing strategies, load factor and clustering effects.', 'Hashing; occupancy/load factor; collision management; expected constant-time access under suitable assumptions.', 'Collision resolution preserves correct hash-table operations when distinct keys produce the same hash-table index. Performance depends on the hash function, load factor and resolution strategy.', 'Hash functions; hash tables; load factor', 'Active'), ('KCR_000010', 'Truth tables', 'Engineering & Technology', 'Discrete Mathematics', 'Abstract Concept', 'A tabular method for evaluating the truth value of a propositional or logical expression for every possible assignment of its component propositions.', 'Logical connectives, compound propositions, equivalence, tautology, contradiction and satisfiability checks.', 'Boolean semantics; compositional evaluation; logical equivalence.', 'Truth tables provide exhaustive finite evaluation of propositional expressions and can establish equivalence or identify tautological and contradictory forms.', 'Propositional logic; Boolean algebra; Boolean semantics; compositional evaluation; logical equivalence; Discrete Mathematics', 'Active'), ('KCR_000011', 'Induction', 'Engineering & Technology', 'Discrete Mathematics', 'Abstract Concept', 'A proof method in which a statement is established for an initial case and then shown to hold for the next case assuming it holds for the current case.', 'Weak/ordinary induction, strong induction, base case, inductive hypothesis and inductive step.', 'Logical implication; well-founded progression; proof by cases over natural-number structure.', 'Mathematical induction proves statements over suitably ordered discrete domains by combining a base case with an inductive argument. Strong induction permits use of multiple earlier cases.', 'Logic; natural numbers; proof techniques', 'Active'), ('KCR_000012', 'Equivalence relations', 'Engineering & Technology', 'Discrete Mathematics', 'Abstract Concept', 'A binary relation that is reflexive, symmetric and transitive, thereby partitioning a set into equivalence classes.', 'Relation properties, equivalence classes, partitions and representative elements.', 'Reflexivity; symmetry; transitivity; partitioning.', 'An equivalence relation identifies elements that are considered equivalent under the relation and induces a partition of the underlying set into disjoint equivalence classes.', 'Relations; sets; partitions', 'Active'), ('KCR_000013', 'Pigeonhole principle', 'Engineering & Technology', 'Discrete Mathematics', 'Abstract Concept', 'A counting principle stating that placing more objects than containers into those containers forces at least one container to contain more than one object.', 'Basic and generalized forms, counting arguments and existence proofs.', 'Counting; cardinality; unavoidable repetition.', 'The pigeonhole principle establishes existence results by comparing the cardinalities of objects and available categories without requiring construction of the repeated case.', 'Sets; counting; cardinality', 'Active'), ('KCR_000014', 'Trees', 'Engineering & Technology', 'Discrete Mathematics', 'Technical Concept', 'A connected acyclic graph used to represent hierarchical or recursive relationships.', 'Rooted trees, parent/child relationships, degree, height, depth, traversal and common tree representations.', 'Hierarchy; connectivity; acyclicity; recursive decomposition.', 'Trees provide hierarchical representations with unique paths between nodes in the underlying undirected tree. Rooted trees support traversal and recursive algorithms.', 'Graphs; recursion; tree traversal', 'Active'), ('KCR_000015', 'Entities, relationships & constraints', 'Engineering & Technology', 'Database Management Systems', 'Technical Concept', 'Core components of conceptual database modelling in which entities represent distinguishable objects, relationships represent associations, and constraints specify valid states.', 'Entity sets, attributes, relationship sets, cardinality/participation constraints, keys and integrity constraints.', 'Data modelling; integrity; identity; structural constraints.', 'Conceptual database modelling captures information requirements independently of physical storage. Entities and relationships are constrained to preserve semantic and integrity requirements.', 'ER modelling; keys; integrity constraints', 'Active'), ('KCR_000016', 'Relational algebra', 'Engineering & Technology', 'Database Management Systems', 'Technical Concept', 'A formal procedural query language based on operations over relations, producing relations as results.', 'Selection, projection, union, difference, Cartesian product, joins, renaming and derived operations.', 'Closure; relational composition; set semantics; query transformation.', 'Relational algebra provides a mathematical basis for relational query processing. Operators transform relations while preserving a relation-valued result.', 'Relations; selection; projection; joins', 'Active'), ('KCR_000017', 'SQL queries', 'Engineering & Technology', 'Database Management Systems', 'Technical Concept', 'Declarative statements used to define, retrieve, manipulate and control data in relational database systems.', 'SELECT queries, filtering, joins, grouping, aggregation, subqueries and data modification statements.', 'Declarative querying; set-oriented processing; integrity; transaction semantics.', 'SQL expresses database operations at a logical level while the DBMS determines an execution strategy. Query correctness depends on relational semantics, constraints and transaction context.', 'Relational model; relational algebra; joins', 'Active'), ('KCR_000018', 'Boyce-Codd Normal Form', 'Engineering & Technology', 'Database Management Systems', 'Technical Concept', 'A relational normal form in which every determinant of a non-trivial functional dependency is a superkey.', 'Functional dependencies, candidate keys, determinants, decomposition and lossless/dependency-preserving considerations.', 'Functional dependency; key-based determination; redundancy reduction.', 'BCNF strengthens normalization by requiring every non-trivial functional dependency to have a superkey determinant. Decomposition may be needed to remove update anomalies.', 'Functional dependencies; candidate keys; 3NF', 'Active'), ('KCR_000019', 'Concurrency control', 'Engineering & Technology', 'Database Management Systems', 'Method / Process', 'Database mechanisms that coordinate concurrent transactions so that their interleaved execution preserves required correctness properties.', 'Serializability, locking, timestamps, isolation, conflicts, deadlock interaction and recovery considerations.', 'Isolation; serializability; consistency; conflict management.', 'Concurrency control regulates interleaved transactions to prevent undesirable anomalies while allowing useful parallelism. Common approaches include two-phase locking and timestamp-based methods.', 'Transactions; serializability; locking', 'Active'), ('KCR_000020', 'Deadlocks', 'Engineering & Technology', 'Operating Systems', 'Technical Concept', 'A state in which a set of processes or threads are permanently blocked because each waits for a resource or event held or controlled by another member of the set.', 'Necessary conditions, resource-allocation graphs, prevention, avoidance, detection and recovery.', 'Mutual exclusion; hold-and-wait; circular wait; resource allocation.', 'Operating-system deadlock analysis identifies cyclic waiting dependencies and methods for preventing, avoiding, detecting or recovering from them.', 'Resource allocation; process synchronization; Mutual exclusion; hold-and-wait; circular wait; Operating Systems', 'Active'), ('KCR_000021', 'Thread synchronization', 'Engineering & Technology', 'Operating Systems', 'Technical Concept', 'Coordination mechanisms that control the ordering and mutual access of concurrent threads to shared state.', 'Critical sections, mutexes/locks, semaphores, monitors, condition variables, race conditions and atomicity.', 'Mutual exclusion; ordering; atomicity; visibility.', 'Thread synchronization prevents or controls race conditions and establishes required ordering between concurrent operations accessing shared resources.', 'Concurrency; critical sections; locks', 'Active'), ('KCR_000022', 'Scheduling algorithms', 'Engineering & Technology', 'Operating Systems', 'Method / Process', 'Algorithms used by an operating system to select processes or threads for execution and allocate processor time.', 'FCFS, SJF/SRTF, priority, round-robin and multilevel scheduling; response, waiting and turnaround metrics.', 'Fairness; responsiveness; throughput; processor utilization.', 'CPU scheduling determines execution order under stated policies and objectives. Different algorithms trade off response time, waiting time, throughput and fairness.', 'Processes/threads; CPU management; Fairness; responsiveness; throughput; processor utilization', 'Active'), ('KCR_000023', 'Paging and virtual memory', 'Engineering & Technology', 'Operating Systems', 'Technical Concept', 'Memory-management techniques that divide address spaces into pages and physical memory into frames, allowing virtual addresses to be mapped to physical locations.', 'Page tables, address translation, page faults, demand paging, replacement and working-set considerations.', 'Address-space abstraction; locality; protection; memory utilization.', 'Paging separates virtual address spaces from physical memory. Virtual memory can extend the apparent address space and support protection, but page faults incur substantial latency.', 'Memory management; address translation; Address-space abstraction; locality; protection; memory utilization', 'Active'), ('KCR_000024', 'File allocation and organization', 'Engineering & Technology', 'Operating Systems', 'Method / Process', 'Methods by which an operating system organizes files and allocates storage blocks to represent their contents.', 'Contiguous, linked and indexed allocation, directories, free-space management and access patterns.', 'Storage organization; locality; allocation efficiency; reliability.', 'File allocation determines how file blocks are placed and accessed on storage. Choices affect sequential/random access, fragmentation, metadata overhead and reliability.', 'File systems; storage management; Storage organization; locality; allocation efficiency; reliability', 'Active'), ('KCR_000025', 'Arithmetic Logic Unit (ALU)', 'Engineering & Technology', 'Computer Architecture', 'Technical Concept', 'The arithmetic logic unit is a processor datapath component that performs arithmetic, logical and related bitwise operations on operands.', 'Arithmetic operations, logical operations, flags/status outputs, operand width and datapath integration.', 'Combinational logic; arithmetic; Boolean operations; datapath design.', 'The ALU implements fundamental computational operations within a processor datapath. Its design influences instruction execution, latency, area and energy use.', 'Processor datapath; arithmetic circuits; Combinational logic; arithmetic; Boolean operations; datapath design', 'Active'), ('KCR_000026', 'Reduced Instruction Set Computer / Complex Instruction Set Computer (RISC/CISC)', 'Engineering & Technology', 'Computer Architecture', 'Technical Concept', 'Two broad instruction-set design approaches distinguished by how instruction complexity, encoding, addressing and implementation responsibilities are organized.', 'Instruction complexity, instruction formats, addressing modes, register use, code density and implementation trade-offs.', 'Instruction-set abstraction; implementation trade-offs; performance; code density.', 'RISC designs generally favor simpler, more regular instructions, while CISC designs may provide richer instruction semantics. Modern processors can combine characteristics of both approaches.', 'Instruction sets; processor architecture; Instruction-set abstraction; implementation trade-offs; performance; code density', 'Active'), ('KCR_000027', 'Pipeline hazards', 'Engineering & Technology', 'Computer Architecture', 'Technical Concept', 'Conditions in a pipelined processor that prevent the next instruction from proceeding through the pipeline as scheduled.', 'Structural, data and control hazards; stalls, forwarding, scheduling and branch handling.', 'Pipeline parallelism; dependency management; throughput.', 'Pipeline hazards arise from resource conflicts, data dependencies or control-flow changes. Hardware and compiler techniques reduce their effect on pipeline throughput.', 'Instruction pipeline; dependencies; Pipeline parallelism; dependency management; throughput; Computer Architecture', 'Active'), ('KCR_000028', 'Caches and virtual memory', 'Engineering & Technology', 'Computer Architecture', 'Technical Concept', 'Memory-hierarchy mechanisms that exploit locality: caches retain frequently used data near processors, while virtual memory maps virtual addresses to physical storage.', 'Cache levels, locality, mapping, replacement, write policies, TLBs and page translation.', 'Locality; hierarchy; address translation; latency reduction.', 'Caches reduce average memory-access latency by exploiting temporal and spatial locality. Virtual memory provides address-space abstraction and protection; TLBs accelerate address translation.', 'Memory hierarchy; paging; locality', 'Active'), ('KCR_000029', 'I/O organization and interfaces', 'Engineering & Technology', 'Computer Architecture', 'Technical Concept', 'Processor and system mechanisms used to communicate with peripheral devices and external interfaces.', 'Programmed I/O, interrupts, DMA, buses, device controllers and interface protocols.', 'Data transfer; synchronization; buffering; device abstraction.', 'I/O organization manages transfers between processors, memory and peripherals using mechanisms such as interrupts and DMA, balancing throughput, latency and processor involvement.', 'I/O devices; interrupts; DMA', 'Active'), ('KCR_000030', 'Merge sort', 'Engineering & Technology', 'Design and Analysis of Algorithms', 'Technical Concept', 'A stable comparison-based sorting algorithm that recursively divides a sequence and merges sorted sub-sequences.', 'Divide-and-conquer decomposition, merge operation, stability and auxiliary storage.', 'Divide and conquer; ordering; stability; predictable complexity.', 'Merge sort has O(n log n) time in the standard comparison model and typically uses O(n) auxiliary storage for array implementations.', 'Divide and conquer; sorting; ordering; stability; predictable complexity; Design and Analysis of Algorithms', 'Active'), ('KCR_000031', 'Knapsack', 'Engineering & Technology', 'Design and Analysis of Algorithms', 'Technical Concept', 'A family of optimization problems that selects items under a capacity constraint to maximize total value.', 'For 0/1 knapsack, each item is selected at most once; state formulation, recurrence, dynamic programming and capacity/value constraints.', 'Combinatorial optimization; optimal substructure; resource allocation; capacity constraints.', 'The 0/1 knapsack problem models discrete selection under a capacity constraint and admits pseudo-polynomial dynamic programming based on capacity. Fractional knapsack is a distinct variant with a greedy optimal solution.', 'Dynamic programming; optimization; Combinatorial optimization; optimal substructure; resource allocation; capacity constraints', 'Active'), ('KCR_000032', 'Activity selection', 'Engineering & Technology', 'Design and Analysis of Algorithms', 'Method / Process', 'A scheduling problem that selects a maximum-size subset of mutually compatible activities given start and finish times.', 'Compatibility, earliest-finish-time greedy rule, selection sequence and proof of optimality.', 'Greedy choice; feasibility; optimal substructure.', 'The standard activity-selection problem is solved optimally by repeatedly selecting the compatible activity with the earliest finish time.', 'Greedy algorithms; scheduling; Greedy choice; feasibility; optimal substructure; Design and Analysis of Algorithms', 'Active'), ('KCR_000033', 'Network flow', 'Engineering & Technology', 'Design and Analysis of Algorithms', 'Technical Concept', 'A graph-based optimization model in which flow is sent through directed edges subject to capacity constraints from a source toward a sink.', 'Flow conservation, capacities, residual networks, augmenting paths, max-flow/min-cut and common algorithms.', 'Conservation; capacity constraints; residual improvement; optimality.', 'Maximum-flow algorithms repeatedly improve a feasible flow using residual capacity. The max-flow/min-cut theorem links maximum flow value to a minimum source-sink cut capacity.', 'Graphs; optimization; residual networks', 'Active'), ('KCR_000034', 'NP-complete problems', 'Engineering & Technology', 'Design and Analysis of Algorithms', 'Technical Concept', 'Decision problems that are both in NP and NP-hard, meaning every problem in NP can be polynomial-time reduced to them.', 'Polynomial verification, polynomial-time reductions, NP-hardness and representative problems.', 'Computational complexity; reduction; tractability boundaries.', 'NP-completeness characterizes decision problems believed not to have polynomial-time algorithms unless P=NP. Proofs typically establish membership in NP and NP-hardness by reduction.', 'Complexity classes; reductions; Computational complexity; reduction; tractability boundaries; Design and Analysis of Algorithms', 'Active'), ('KCR_000035', 'Process models', 'Engineering & Technology', 'Software Engineering', 'Method / Process', 'Structured approaches for organizing software development activities, deliverables and control points across a development lifecycle.', 'Waterfall, iterative/incremental, spiral, agile and hybrid lifecycle approaches; activities, feedback and change management.', 'Lifecycle management; iteration; risk; stakeholder feedback.', 'Software process models organize requirements, design, implementation, verification and evolution. Their suitability depends on uncertainty, risk, constraints and stakeholder needs.', 'Software lifecycle; development processes; Lifecycle management; iteration; risk; stakeholder feedback', 'Active'), ('KCR_000036', 'Continuous integration and delivery', 'Engineering & Technology', 'Software Engineering', 'Technical Concept', 'Software engineering practices that automate frequent integration, verification and delivery of software changes through a controlled pipeline.', 'Build automation, version control integration, automated tests, artifact management, deployment automation and release controls.', 'Automation; repeatability; feedback; quality assurance; traceability.', 'Continuous integration detects integration problems through frequent automated builds and tests. Continuous delivery keeps software in a releasable state through automated and controlled delivery practices.', 'Version control; automated testing; deployment pipelines', 'Active'), ('KCR_000037', 'Use cases and requirements specification', 'Engineering & Technology', 'Software Engineering', 'Technical Concept', 'Techniques for eliciting, documenting and validating required system behaviour, qualities and constraints from stakeholder needs.', 'Functional/non-functional requirements, actors, use cases, scenarios, acceptance criteria, traceability and validation.', 'Stakeholder needs; completeness; consistency; verifiability; traceability.', 'Requirements engineering translates stakeholder needs into specifications that can be analyzed, validated and traced. Use cases primarily describe interactions and externally observable behaviour.', 'Requirements engineering; use cases; Stakeholder needs; completeness; consistency; verifiability', 'Active'), ('KCR_000038', 'Design patterns', 'Engineering & Technology', 'Software Engineering', 'Method / Process', 'Reusable, named design solutions to recurring software design problems within a stated context and set of trade-offs.', 'Creational, structural and behavioural patterns; participants, collaborations, consequences and applicability.', 'Abstraction; coupling/cohesion; reuse; trade-offs.', 'Design patterns document recurring design structures rather than finished code. Their value depends on context, appropriate abstraction and explicit trade-offs.', 'Object-oriented design; software architecture; Abstraction; coupling/cohesion; reuse; trade-offs', 'Active'), ('KCR_000039', 'Unit and integration testing', 'Engineering & Technology', 'Software Engineering', 'Method / Process', 'Testing practices that verify individual software units and their interactions with collaborating components.', 'Test cases, fixtures, mocks/stubs, unit boundaries, integration strategies, interfaces and defect isolation.', 'Verification; isolation; interface correctness; regression detection.', 'Unit tests focus on small software components, while integration tests examine interactions across component boundaries. Both support regression detection and defect localization.', 'Software testing; verification; isolation; interface correctness; regression detection; Software Engineering', 'Active'), ('KCR_000040', 'Transmission media and signalling', 'Engineering & Technology', 'Computer Networks', 'Technical Concept', 'Physical means and signalling methods used to carry information across a communication channel.', 'Copper, fibre and wireless media; bandwidth, attenuation, noise, modulation/encoding and transmission characteristics.', 'Signal integrity; bandwidth; attenuation; interference.', 'Transmission media determine physical propagation characteristics, while signalling maps information to physical signals. Channel properties constrain achievable data rates and reliability.', 'Physical layer; communication channels; Signal integrity; bandwidth; attenuation; interference', 'Active'), ('KCR_000041', 'Framing and MAC', 'Engineering & Technology', 'Computer Networks', 'Technical Concept', 'Data-link mechanisms that delimit frames and control access to a shared or point-to-point communication medium.', 'Frame structure, error detection, MAC addressing, Ethernet, collision handling and medium-access methods.', 'Framing; addressing; error detection; medium access.', 'Framing packages network-layer data for link transmission, while MAC mechanisms govern how stations access a shared medium and identify link-layer endpoints.', 'Data link layer; Ethernet; Framing; addressing; error detection; medium access', 'Active'), ('KCR_000042', 'IP addressing and routing', 'Engineering & Technology', 'Computer Networks', 'Technical Concept', 'Network-layer mechanisms for identifying interfaces or endpoints and selecting paths for forwarding packets between networks.', 'IPv4/IPv6 addressing, subnetting, forwarding tables, routing principles and route selection.', 'Hierarchical addressing; forwarding; reachability; path selection.', 'IP addressing identifies network-layer interfaces using address structures, while routing determines next-hop paths across interconnected networks.', 'IP; subnetting; routing', 'Active'), ('KCR_000043', 'Transmission Control Protocol / User Datagram Protocol (TCP/UDP)', 'Engineering & Technology', 'Computer Networks', 'Technical Concept', 'Transport-layer protocols represented by TCP, a connection-oriented reliable byte-stream protocol, and UDP, a connectionless datagram transport.', 'Ports, multiplexing, TCP sequencing/acknowledgement/congestion control and UDP datagrams.', 'End-to-end transport; multiplexing; reliability; congestion management.', 'TCP provides ordered reliable byte-stream delivery with flow and congestion control. UDP provides minimal datagram transport without TCP''s reliability, ordering or congestion-control semantics.', 'Transport layer; sockets; End-to-end transport; multiplexing; reliability; congestion management', 'Active'), ('KCR_000044', 'Hypertext Transfer Protocol (HTTP)', 'Engineering & Technology', 'Computer Networks', 'Technical Concept', 'An application-layer request/response protocol used for transferring web resources and related representations.', 'Methods, status codes, headers, message semantics, caching, persistent connections and HTTP over secure transports.', 'Request/response; resource identification; stateless application semantics; extensibility.', 'HTTP defines application-level semantics for exchanging requests and responses. Web security and confidentiality are normally provided by using HTTP over TLS.', 'Application layer; web protocols; Request/response; resource identification; stateless application semantics; extensibility', 'Active'), ('KCR_000045', 'Hooke''s Law', 'Engineering & Technology', 'Mechanics of Materials', 'Principle / Criterion', 'Within the linear elastic range of a material, stress is proportional to strain for the relevant loading mode.', 'Normal stress/strain relation, elastic modulus, proportional limit and applicability to linear elasticity.', 'Elasticity; proportionality; material stiffness.', 'Hooke''s law provides the constitutive relation for linear elastic response, such as σ=Eε in uniaxial loading under the applicable assumptions.', 'Stress-strain relation; elastic modulus; Elasticity; proportionality; material stiffness; Mechanics of Materials', 'Active'), ('KCR_000046', 'Flexure formula', 'Engineering & Technology', 'Mechanics of Materials', 'Principle / Criterion', 'The beam flexure relation that connects bending stress to bending moment, cross-sectional geometry and distance from the neutral axis under stated beam assumptions.', 'σ = My/I, neutral axis, second moment of area, bending moment and elastic-beam assumptions.', 'Equilibrium; compatibility; elastic bending; section geometry.', 'The flexure formula is derived for slender beams under linear-elastic, small-deflection conditions where plane sections remain approximately plane.', 'Bending moment; second moment of area; Equilibrium; compatibility; elastic bending; section geometry', 'Active'), ('KCR_000047', 'Bending stress distribution', 'Engineering & Technology', 'Mechanics of Materials', 'Technical Concept', 'The spatial variation of normal bending stress across a beam cross-section caused by an applied bending moment.', 'Linear stress distribution in elastic homogeneous sections, neutral axis, extreme fibres and section modulus.', 'Stress distribution; neutral axis; section geometry.', 'For elastic bending of a homogeneous beam under the standard assumptions, bending stress varies linearly with distance from the neutral axis and reaches maximum magnitude at the extreme fibres.', 'Flexure formula; section modulus; Stress distribution; neutral axis; section geometry; Mechanics of Materials', 'Active'), ('KCR_000048', 'Circular shafts', 'Engineering & Technology', 'Mechanics of Materials', 'Technical Concept', 'Cylindrical structural members designed to transmit torque and resist associated torsional stresses and deformation.', 'Solid/hollow shafts, torque, polar moment of inertia, torsional shear stress, angle of twist and power transmission.', 'Torsion; shear stress; stiffness; strength.', 'Circular-shaft torsion relates applied torque to shear stress and twist using the polar second moment of area under the assumptions of elastic Saint-Venant torsion.', 'Torsion; polar moment; shear stress; stiffness; strength; Mechanics of Materials', 'Active'), ('KCR_000049', 'Beam deflection methods', 'Engineering & Technology', 'Mechanics of Materials', 'Technical Concept', 'Analytical methods used to determine displacement and slope of beams under transverse loading.', 'Double integration, singularity functions, moment-area, conjugate beam and related elastic methods.', 'Compatibility; stiffness; deformation; boundary conditions.', 'Beam deflection methods determine slope and displacement from load, bending stiffness and boundary conditions under linear-elastic beam assumptions.', 'Flexure; moment-area theorem; Compatibility; stiffness; deformation; boundary conditions', 'Active'), ('KCR_000050', 'Viscosity', 'Engineering & Technology', 'Fluid Mechanics; Hydraulics and Hydraulic Engineering; Fluid Flow and Heat Transfer', 'Technical Concept', 'A measure of a fluid’s resistance to deformation and flow, arising from internal friction and relating shear stress to velocity gradient under Newtonian conditions.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Viscosity.', 'Dynamic viscosity relates shear stress to velocity gradient for a Newtonian fluid. Kinematic viscosity is dynamic viscosity divided by density.', 'Newtonian fluids; shear stress; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Viscosity', 'Active') ON CONFLICT DO NOTHING;